pm.collectionVariables.unset("toppingIds");

pm.test("Topping catalogue is valid", () => {
    pm.response.to.have.status(200);

    const ingredients = pm.response.json().ingredients;
    pm.expect(ingredients).to.be.an("array").and.not.empty;

    ingredients.forEach(item => {
        pm.expect(item.ID).to.be.a("number");
    });

    pm.collectionVariables.set(
        "toppingIds",
        JSON.stringify(ingredients.map(item => item.ID))
    );
});

const body = pm.response.json();

pm.test("Status is 200", () => {
    pm.response.to.have.status(200);
});

pm.test("Pizza response has the expected structure", () => {
    pm.expect(body.pizza).to.be.an("object");
    pm.expect(body.pizza.id).to.be.a("number");
    pm.expect(body.pizza.name).to.be.a("string").and.not.empty;
    pm.expect(body.pizza.ingredients).to.be.an("array").and.not.empty;
    pm.expect(body.calories).to.be.a("number");
    pm.expect(body.vegetarian).to.be.a("boolean");
});

pm.test("Pizza and every ingredient are vegetarian", () => {
    pm.expect(body.vegetarian).to.equal(true);

    body.pizza.ingredients.forEach(ingredient => {
        pm.expect(ingredient.vegetarian, ingredient.name).to.equal(true);
    });
});

pm.test("Anchovies and bacon are excluded", () => {
    body.pizza.ingredients.forEach(ingredient => {
        const name = ingredient.name.toLowerCase();
        pm.expect(name).not.to.include("anchov");
        pm.expect(name).not.to.include("bacon");
    });
});

pm.test("Calories stay within the requested limit", () => {
    pm.expect(body.calories).to.be.at.least(0);
    pm.expect(body.calories).to.be.at.most(800);
});

pm.test("Topping count follows requested limits", () => {
    const savedIds = pm.collectionVariables.get("toppingIds");
    pm.expect(savedIds, "Run Get topping catalogue first")
        .to.be.a("string").and.not.empty;

    const toppingIds = new Set(JSON.parse(savedIds));
    const restrictions = JSON.parse(pm.request.body.raw);

    const toppings = body.pizza.ingredients.filter(
        ingredient => toppingIds.has(ingredient.ID)
    );

    pm.expect(toppings.length).to.be.within(
        restrictions.minNumberOfToppings,
        restrictions.maxNumberOfToppings
    );
});

pm.test("Dough is present and valid", () => {
    pm.expect(body.pizza.dough).to.be.an("object");
    pm.expect(body.pizza.dough.name).to.be.a("string");
    pm.expect(body.pizza.dough.caloriesPerSlice).to.be.a("number");
});
